    "rationale": "The **tentorium cerebelli** separates the supratentorial (cerebrum) from the subtentorial (cerebellum, brainstem) compartments. It has a central opening (tentorial notch/incisura). Expanding supratentorial mass \u2192 shifts medial temporal lobe (uncus) downward through the tentorial notch (**uncal herniation**) \u2192 compresses ipsilateral CN III (parasympathetic fibers on the outside \u2192 blown pupil first) \u2192 ptosis, mydriasis, eye down and out \u2192 progresses to coma, Cushing response, and death.",
